package com.classvoice.controller; import com.classvoice.dao.*; import com.classvoice.model.*; import com.classvoice.service.TopicMatchingService; import com.classvoice.util.WebUtil; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.IOException; import java.util.*;
@WebServlet("/student/feedback") public class SubmitFeedbackServlet extends HttpServlet {
 private LectureDAO lectures=new LectureDAO(); private TopicDAO topics=new TopicDAO(); private FeedbackDAO feedback=new FeedbackDAO(); private TopicMatchingService matcher=new TopicMatchingService();
 protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{try{long id=WebUtil.longParam(r,"lectureId");Lecture l=lectures.findById(id);if(l==null){p.sendError(404);return;}r.setAttribute("lecture",l);r.getRequestDispatcher("/WEB-INF/views/submit-feedback.jsp").forward(r,p);}catch(Exception e){throw new ServletException(e);}}
 protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{long id=WebUtil.longParam(r,"lectureId");String text=WebUtil.trim(r.getParameter("feedbackText"));try{Lecture l=lectures.findById(id);if(l==null){p.sendError(404);return;}String err=null;if(!l.isActive())err="This lecture is not active for feedback right now.";else if(text.isBlank())err="Please enter what you did not understand.";else if(text.length()>1000)err="Feedback must be 1000 characters or fewer.";if(err!=null){r.setAttribute("lecture",l);r.setAttribute("error",err);r.setAttribute("feedbackTextValue",text);r.getRequestDispatcher("/WEB-INF/views/submit-feedback.jsp").forward(r,p);return;}List<Topic> ts=topics.findByLecture(id);Topic matched=matcher.findBestTopic(text,ts);User u=(User)r.getSession().getAttribute("user");Feedback f=new Feedback();f.setLectureId(id);f.setStudentId(u.getUserId());f.setTopicId(matched==null?null:matched.getTopicId());f.setFeedbackText(text);feedback.create(f);r.setAttribute("matchedTopic",matched==null?"Other / Uncategorized":matched.getTopicName());r.setAttribute("lecture",l);r.getRequestDispatcher("/WEB-INF/views/feedback-success.jsp").forward(r,p);}catch(Exception e){throw new ServletException(e);}}
}
